async function json(url){const response=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('服务暂时无法访问，请稍后重试');return response.json()}
export async function findCities(name){const data=await json('https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:name.trim().toLowerCase()==='lisboa'?'Lisbon':name,count:6,language:'zh',format:'json'}));return data.results||[]}
export async function weather(city){const p=new URLSearchParams({latitude:city.latitude,longitude:city.longitude,timezone:'auto',forecast_days:7,current:'temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,uv_index_max,wind_speed_10m_max'});const data=await json('https://api.open-meteo.com/v1/forecast?'+p);if(!data.current||!data.daily)throw Error('天气数据不完整');return {...data,fetchedAt:Date.now(),city:city.name}}
export function weatherText(code){if(code===0)return'晴';if(code<4)return'多云';if(code<50)return'雾';if(code<70)return'雨';if(code<80)return'雪';if(code<90)return'阵雨';return'雷暴'}
